create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique, display_name text, bio text not null default '', avatar_url text, created_at timestamptz not null default now());
create table if not exists public.books (id text primary key, title text not null, author text not null, description text not null default '', cover_url text, genre text, published_year int, pages int, quote text, created_at timestamptz not null default now());
create table if not exists public.reviews (id uuid primary key default gen_random_uuid(), book_id text not null references public.books(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, rating int not null check (rating between 1 and 5), body text not null check (char_length(body) between 3 and 5000), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(book_id, user_id));
create table if not exists public.review_likes (review_id uuid not null references public.reviews(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(review_id, user_id));
create table if not exists public.comments (id uuid primary key default gen_random_uuid(), review_id uuid not null references public.reviews(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, body text not null check (char_length(body) between 1 and 1000), created_at timestamptz not null default now());
create table if not exists public.shelves (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, book_id text not null references public.books(id) on delete cascade, status text not null check(status in ('want_to_read','reading','finished','favorite')), progress int not null default 0 check(progress between 0 and 100), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, book_id));
create table if not exists public.follows (follower_id uuid not null references public.profiles(id) on delete cascade, following_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(follower_id, following_id), check(follower_id <> following_id));
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, actor_id uuid references public.profiles(id) on delete cascade, type text not null check(type in ('like','comment','follow','review')), review_id uuid references public.reviews(id) on delete cascade, message text not null, read_at timestamptz, created_at timestamptz not null default now());
create index if not exists reviews_book_idx on public.reviews(book_id, created_at desc); create index if not exists reviews_user_idx on public.reviews(user_id, created_at desc); create index if not exists shelves_user_idx on public.shelves(user_id, status); create index if not exists comments_review_idx on public.comments(review_id, created_at); create index if not exists notifications_user_idx on public.notifications(user_id, created_at desc);
alter table public.profiles enable row level security; alter table public.books enable row level security; alter table public.reviews enable row level security; alter table public.review_likes enable row level security; alter table public.comments enable row level security; alter table public.shelves enable row level security; alter table public.follows enable row level security; alter table public.notifications enable row level security;
create policy "profiles are public" on public.profiles for select using (true); create policy "users create own profile" on public.profiles for insert with check (auth.uid() = id); create policy "users update own profile" on public.profiles for update using (auth.uid() = id);
create policy "books are public" on public.books for select using (true);
create policy "reviews are public" on public.reviews for select using (true); create policy "users create own reviews" on public.reviews for insert with check (auth.uid() = user_id); create policy "users update own reviews" on public.reviews for update using (auth.uid() = user_id); create policy "users delete own reviews" on public.reviews for delete using (auth.uid() = user_id);
create policy "likes are public" on public.review_likes for select using (true); create policy "users manage own likes" on public.review_likes for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "comments are public" on public.comments for select using (true); create policy "users create own comments" on public.comments for insert with check (auth.uid() = user_id); create policy "users manage own comments" on public.comments for update using (auth.uid() = user_id); create policy "users delete own comments" on public.comments for delete using (auth.uid() = user_id);
create policy "users manage own shelves" on public.shelves for all using (auth.uid() = user_id) with check (auth.uid() = user_id); create policy "own shelves are readable" on public.shelves for select using (auth.uid() = user_id);
create policy "follows are public" on public.follows for select using (true); create policy "users manage own follows" on public.follows for all using (auth.uid() = follower_id) with check (auth.uid() = follower_id);
create policy "users read own notifications" on public.notifications for select using (auth.uid() = user_id); create policy "users update own notifications" on public.notifications for update using (auth.uid() = user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, username, display_name) values (new.id, split_part(new.email, '@', 1), coalesce(new.raw_user_meta_data->>'display_name', split_part(new.email, '@', 1))) on conflict (id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
drop trigger if exists reviews_touch_updated_at on public.reviews; create trigger reviews_touch_updated_at before update on public.reviews for each row execute procedure public.touch_updated_at();
drop trigger if exists shelves_touch_updated_at on public.shelves; create trigger shelves_touch_updated_at before update on public.shelves for each row execute procedure public.touch_updated_at();
